409	    private void validateRequiredFields(OwnerFieldsDto ownerFieldsDto) {
410	        List<String> missing = new ArrayList<>();
411	        addIfBlank(missing, "firstName", ownerFieldsDto.getFirstName());
412	        addIfBlank(missing, "lastName", ownerFieldsDto.getLastName());
