427	    /**
428	     * Normalizes a submitted telephone number into E.164 form. Spaces, dashes and brackets
429	     * are stripped. When a leading {@code '+'} and country code are present they are kept as
430	     * given; otherwise the country code {@code '+61'} is assumed and a single leading
431	     * {@code '0'} is dropped from the national digits. The result must be a {@code '+'}
432	     * followed by 8 to 15 digits. The normalized E.164 value is what gets stored and returned.
433	     * When the value cannot form a valid E.164 number an {@link InvalidFieldsException} is
434	     * thrown, which the exception advice renders as a 400 response naming the {@code telephone}
435	     * field. For example {@code "0412 345 678"} becomes {@code "+61412345678"}.
436	     *
437	     * @param telephone the submitted telephone value
438	     * @return the normalized E.164 telephone
439	     */
440	    private String normalizeTelephone(String telephone) {
441	        String cleaned = telephone == null ? "" : telephone.replaceAll("[\\s\\-()]", "");
442	        String e164;
443	        if (cleaned.startsWith("+")) {
444	            e164 = "+" + cleaned.substring(1);
445	        } else {
446	            String national = cleaned;
447	            if (national.startsWith("0")) {
448	                national = national.substring(1);
449	            }
450	            e164 = "+61" + national;
451	        }
452	        if (!e164.matches("^\\+[0-9]{8,15}$")) {
453	            throw new InvalidFieldsException(List.of("telephone"));
454	        }
455	        return e164;
456	    }
