458	    /**
459	     * Pattern for a syntactically valid email address: a non-empty local part, an {@code @},
460	     * and a domain containing at least one dot, none of the parts holding whitespace or a
461	     * second {@code @}.
462	     */
463	    private static final java.util.regex.Pattern EMAIL_PATTERN =
464	        java.util.regex.Pattern.compile("^[^\\s@]+@[^\\s@]+\\.[^\\s@]+$");
465	
466	    /**
467	     * Normalizes an optional owner email. An email is optional, so a {@code null} value is
468	     * accepted and returned unchanged. When present it must be a syntactically valid address;
469	     * the value is stored and returned lower-cased. When present but invalid an
470	     * {@link InvalidFieldsException} is thrown, which the exception advice renders as a 400
471	     * response naming the {@code email} field.
472	     *
473	     * @param email the submitted email value, or {@code null} when omitted
474	     * @return the lower-cased email, or {@code null} when none was supplied
475	     */
476	    private String normalizeEmail(String email) {
477	        if (email == null) {
478	            return null;
479	        }
480	        String trimmed = email.trim();
481	        if (!EMAIL_PATTERN.matcher(trimmed).matches()) {
482	            throw new InvalidFieldsException(List.of("email"));
483	        }
484	        return canonicalEmail(trimmed);
485	    }
486	
487	    /**
488	     * Reduces an email to the canonical form used both to store it and to compare it against
489	     * other owners' emails: surrounding whitespace is trimmed and the value is lower-cased. A
490	     * {@code null} email (none was supplied) canonicalizes to {@code null}. Unlike
491	     * {@link #normalizeEmail(String)} no validation is performed, so this can be applied to a
492	     * value read back off an existing owner without risk of rejecting it. This is the single
493	     * definition of email identity: two emails denote the same address exactly when they
494	     * canonicalize to the same value, so an email stored via {@link #normalizeEmail(String)} and
495	     * an email already on an existing owner can be compared for equality after both pass through
496	     * here. For example {@code "  Jane@Example.COM "} canonicalizes to {@code "jane@example.com"}.
497	     *
498	     * @param email the email to canonicalize, or {@code null} when none was supplied
499	     * @return the trimmed, lower-cased email, or {@code null} when {@code email} is {@code null}
500	     */
501	    private String canonicalEmail(String email) {
502	        if (email == null) {
503	            return null;
504	        }
505	        return email.trim().toLowerCase(java.util.Locale.ROOT);
506	    }
507	
508	    /**
509	     * Rejects a new owner whose normalized telephone is already used by any existing owner.
510	     * The telephone is stored in its normalized E.164 form, so a plain equality check
511	     * against every owner's telephone compares E.164 values. When a match is found a
512	     * {@link DuplicateTelephoneException} is thrown, which the exception advice renders as a
513	     * 409 Conflict response.
514	     *
515	     * @param telephone the normalized telephone of the owner being created
516	     */
517	    private void rejectDuplicateTelephone(String telephone) {
518	        boolean taken = this.clinicService.findAllOwners().stream()
519	            .anyMatch(existing -> telephone.equals(existing.getTelephone()));
520	        if (taken) {
521	            throw new DuplicateTelephoneException(telephone);
522	        }
523	    }
524	
525	    /**
526	     * Rejects a new owner whose email is already used by any existing owner. An email is
527	     * optional, so a {@code null} email is never a duplicate. When present the email is
528	     * compared to every existing owner's email under the single canonical email identity
529	     * (trimmed and lower-cased, see {@link #canonicalEmail(String)}), so for example
530	     * {@code "Jane@Example.com"} collides with a stored {@code "jane@example.com"}. When a
531	     * match is found a {@link DuplicateEmailException} is thrown, which the exception advice
532	     * renders as a 409 Conflict response.
533	     *
534	     * @param email the normalized email of the owner being created, or {@code null} when omitted
535	     */
536	    private void rejectDuplicateEmail(String email) {
537	        String canonical = canonicalEmail(email);
538	        if (canonical == null) {
539	            return;
540	        }
541	        boolean taken = this.clinicService.findAllOwners().stream()
542	            .anyMatch(existing -> canonical.equals(canonicalEmail(existing.getEmail())));
543	        if (taken) {
544	            throw new DuplicateEmailException(canonical);
545	        }
546	    }
