548	    /**
549	     * Rejects a new owner whose {@code lastName} and {@code address} already belong to another
550	     * owner, i.e. one that shares its household (see {@link #findHouseholdMate(String, String)}
551	     * for how that identity is compared). A request may bypass this rule by setting
552	     * {@code sharesHousehold} to {@code true}, allowing several owners to share one household.
553	     * When a household mate is found and the request did not opt in a
554	     * {@link DuplicateHouseholdException} is thrown, which the exception advice renders as a 409
555	     * Conflict response.
556	     *
557	     * @param ownerFieldsDto the submitted owner fields
558	     */
559	    private void rejectDuplicateHousehold(OwnerFieldsDto ownerFieldsDto) {
560	        if (Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold())) {
561	            return;
562	        }
563	        boolean taken = findHouseholdMate(ownerFieldsDto.getLastName(), ownerFieldsDto.getAddress()).isPresent();
564	        if (taken) {
565	            throw new DuplicateHouseholdException(ownerFieldsDto.getLastName(), ownerFieldsDto.getAddress());
566	        }
567	    }
568	
569	    /**
570	     * Assigns the shared {@code householdId} for an owner created with {@code sharesHousehold}
571	     * set to {@code true}. The identifier is derived deterministically from the owner's
572	     * household identity (its {@code lastName} and {@code address}, see
573	     * {@link #householdIdFor(String, String)}), so every owner in the same household resolves to
574	     * the same stable value. The new owner receives that value, and any existing household mates
575	     * that do not yet carry it are updated so the whole household shares one identifier. When the
576	     * request did not opt in the owner is left without a household identifier.
577	     *
578	     * @param owner the newly created owner, mutated in place with its household identifier
579	     * @param ownerFieldsDto the submitted owner fields carrying the {@code sharesHousehold} flag
580	     */
581	    private void assignHousehold(Owner owner, OwnerFieldsDto ownerFieldsDto) {
582	        if (!Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold())) {
583	            return;
584	        }
585	        String householdId = householdIdFor(owner.getLastName(), owner.getAddress());
586	        owner.setHouseholdId(householdId);
587	        for (Owner mate : findHouseholdMates(owner.getLastName(), owner.getAddress())) {
588	            if (!householdId.equals(mate.getHouseholdId())) {
589	                mate.setHouseholdId(householdId);
590	                this.clinicService.saveOwner(mate);
591	            }
592	        }
593	    }
594	
595	    /**
596	     * Derives the stable {@code householdId} shared by every owner in the household identified by
597	     * the given {@code lastName} and {@code address}. The two fields are normalized exactly as
598	     * household identity is compared elsewhere (case-insensitively, with collapsed whitespace) and
599	     * hashed with SHA-256, so any two owners in the same household — regardless of creation order —
600	     * resolve to the same identifier. The result is formatted as {@code 'HH-<16 hex chars>'}.
601	     *
602	     * @param lastName the household's last name
603	     * @param address the household's address
604	     * @return the deterministic household identifier
605	     */
606	    private String householdIdFor(String lastName, String address) {
607	        String key = collapseWhitespace(lastName).toLowerCase(java.util.Locale.ROOT) + "|"
608	            + normalizeAddress(address).toLowerCase(java.util.Locale.ROOT);
609	        try {
610	            byte[] digest = java.security.MessageDigest.getInstance("SHA-256")
611	                .digest(key.getBytes(java.nio.charset.StandardCharsets.UTF_8));
612	            StringBuilder sb = new StringBuilder();
613	            for (int i = 0; i < 8; i++) {
614	                sb.append(String.format("%02X", digest[i]));
615	            }
616	            return "HH-" + sb;
617	        }
618	        catch (java.security.NoSuchAlgorithmException e) {
619	            throw new IllegalStateException("SHA-256 is required but unavailable", e);
620	        }
621	    }
622	
623	    /**
624	     * Counts the owners that belong to the household identified by the given {@code householdId},
625	     * i.e. every owner carrying that exact identifier. The count is taken against the current set
626	     * of owners, so after a create it reflects the household's size including the newly persisted
627	     * owner. An owner without a household (a {@code null} identifier) belongs to no shared
628	     * household and yields {@code 0}.
629	     *
630	     * @param householdId the shared household identifier, or {@code null} when the owner shares no household
631	     * @return the number of owners in the household, or {@code 0} when {@code householdId} is {@code null}
632	     */
633	    private int countHouseholdMembers(String householdId) {
634	        if (householdId == null) {
635	            return 0;
636	        }
637	        return (int) this.clinicService.findAllOwners().stream()
638	            .filter(existing -> householdId.equals(existing.getHouseholdId()))
639	            .count();
640	    }
