642	    /**
643	     * Finds an existing owner that shares a household with the given {@code lastName} and
644	     * {@code address}. When several owners match, the first one encountered is returned.
645	     *
646	     * @param lastName the last name to match on
647	     * @param address the address to match on
648	     * @return the first owner sharing the household, or empty when none exists
649	     */
650	    private Optional<Owner> findHouseholdMate(String lastName, String address) {
651	        return findHouseholdMates(lastName, address).stream().findFirst();
652	    }
653	
654	    /**
655	     * Finds every existing owner that shares a household with the given {@code lastName} and
656	     * {@code address}. Both fields are compared case-insensitively and with runs of whitespace
657	     * collapsed to a single space (and surrounding whitespace trimmed), so for example
658	     * {@code "Franklin"} at {@code "110  W. Liberty St."} matches {@code "franklin"} at
659	     * {@code "110 W. Liberty St."}. This is the single definition of household identity shared by
660	     * every rule that reasons about households.
661	     *
662	     * @param lastName the last name to match on
663	     * @param address the address to match on
664	     * @return the owners sharing the household, in encounter order (possibly empty)
665	     */
666	    private List<Owner> findHouseholdMates(String lastName, String address) {
667	        String normalizedLastName = collapseWhitespace(lastName);
668	        String normalizedAddress = normalizeAddress(address);
669	        return this.clinicService.findAllOwners().stream()
670	            .filter(existing -> normalizedLastName.equalsIgnoreCase(collapseWhitespace(existing.getLastName()))
671	                && normalizedAddress.equalsIgnoreCase(normalizeAddress(existing.getAddress())))
672	            .toList();
673	    }
674	
675	    /**
676	     * Collapses a field for household comparison: leading and trailing whitespace is trimmed and
677	     * every internal run of whitespace is reduced to a single space. A {@code null} value collapses
678	     * to the empty string. Case is left untouched so callers can compare case-insensitively.
679	     *
680	     * @param value the value to collapse, or {@code null}
681	     * @return the whitespace-collapsed value, never {@code null}
682	     */
683	    private String collapseWhitespace(String value) {
684	        if (value == null) {
685	            return "";
686	        }
687	        return value.trim().replaceAll("\\s+", " ");
688	    }
689	
690	    /**
691	     * Common street-type abbreviations expanded during address normalization, keyed by their
692	     * upper-cased token.
693	     */
694	    private static final java.util.Map<String, String> ADDRESS_ABBREVIATIONS =
695	        java.util.Map.of("ST", "STREET", "RD", "ROAD", "AVE", "AVENUE");
696	
697	    /**
698	     * Normalizes a submitted address into the canonical form stored and returned for an owner:
699	     * leading and trailing whitespace is trimmed, every internal run of whitespace is collapsed to
700	     * a single space, the value is upper-cased, and common street-type abbreviations are expanded
701	     * ({@code ST -> STREET}, {@code RD -> ROAD}, {@code AVE -> AVENUE}). A {@code null} value
702	     * normalizes to the empty string, and an address that holds only whitespace normalizes to the
703	     * empty string so the required-field check rejects it. For example {@code "  12  main  st "}
704	     * becomes {@code "12 MAIN STREET"}. This is the single definition of address normalization used
705	     * everywhere an address is stored or compared.
706	     *
707	     * @param address the submitted address value, or {@code null}
708	     * @return the normalized address, never {@code null}
709	     */
710	    private String normalizeAddress(String address) {
711	        if (address == null) {
712	            return "";
713	        }
714	        String collapsed = address.trim().replaceAll("\\s+", " ").toUpperCase(java.util.Locale.ROOT);
715	        if (collapsed.isEmpty()) {
716	            return "";
717	        }
718	        String[] tokens = collapsed.split(" ");
719	        StringBuilder sb = new StringBuilder(collapsed.length());
720	        for (int i = 0; i < tokens.length; i++) {
721	            if (i > 0) {
722	                sb.append(' ');
723	            }
